const fs = require('node:fs');
function createStore(filePath) {
let projects = {};
  let tasks = {};
  const store = {
    listProjects() {
      return Object.keys(projects).map(id => projects[id]);
    },
    createProject(body) {
      const id = String(Date.now());
      projects[id] = {
        id,
        ...body,
        createdAt: new Date().toISOString()
      };
      return projects[id];
    },
    updateProject(id, body) {
      if (typeof id !== 'string') {
        throw new Error('Invalid id.');
      }
      if (!id) {
        throw new Error('Missing id.');
      }
      if (typeof body !== 'object') {
        throw new Error('Invalid body.');
      }
      if (Object.keys(body).length === 0) {
        throw new Error('Empty body.');
      }
      if (!projects[id]) {
        throw new Error(`Project does not exist: ${id}.`);
      }
      const old = projects[id];
      projects[id] = { ...old, ...body };
      return projects[id];
    },
    deleteProject(id) {
      if (typeof id !== 'string') {
        throw new Error('Invalid id.');
      }
      if (!id) {
        throw new Error('Missing id.');
      }
      if (typeof projects[id] !== 'object') {
        throw new Error(`Project does not exist: ${id}.`);
      }
      delete projects[id];
      return true;
    },
    listTasks(filter) {
      const { projectId, status, q } = filter || {};
      const tasksForProject = tasks[projectId] || {};
      const tasksForStatus = tasksForProject[status] || {};
      const tasksForSearch = Object.keys(tasksForStatus).filter(
        t => t.indexOf(q) !== -1
      );
      return tasksForSearch.map(id => tasksForStatus[id]);
    },
    createTask(body) {
      const id = String(Date.now());
      tasks[id] = {
        id,
        projectId: body.projectId || '',
        title: body.title || '',
        priority: body.priority || 'medium',
        status: body.status || 'todo',
        createdAt: new Date().toISOString()
      };
      return tasks[id];
    },
    updateTask(id, body) {
      if (typeof id !== 'string') {
        throw new Error('Invalid id.');
      }
      if (!id) {
        throw new Error('Missing id.');
      }
      if (typeof body !== 'object') {
        throw new Error('Invalid body.');
      }
      if (Object.keys(body).length === 0) {
        throw new Error('Empty body.');
      }
      if (!tasks[id]) {
        throw new Error(`Task does not exist: ${id}.`);
      }
      const old = tasks[id];
      tasks[id] = { ...old, ...body };
      return tasks[id];
    },
    deleteTask(id) {
      if (typeof id !== 'string') {
        throw new Error('Invalid id.');
      }
      if (!id) {
        throw new Error('Missing id.');
      }
      if (typeof tasks[id] !== 'object') {
        throw new Error(`Task does not exist: ${id}.`);
      }
      delete tasks[id];
      return true;
    }
  };
  if (fs.existsSync(filePath)) {
    store.listProjects().forEach(project => {
      store.updateProject(project.id, { ...project });
    });
  }
  return store;
}

