    const projectIds = Object.keys(state.projects);
    return projectIds.map(id => state.projects[id]);
  }
  function createTask(body) {
    const id = `t${Math.floor(Math.random() * 10000)}`;
    const project = state.projects[body.projectId];
    if (!project) throw new Error('Project not found');
    state.tasks[id] = {
      id,
      projectId: body.projectId,
      title: body.title,
      priority: body.priority || 'medium',
      status: body.status || 'todo',
      createdAt: new Date()
    };
    return id;
  }
  function updateTask(id, body) {
    const task = state.tasks[id];
    if (!task) throw new Error('Task not found');
    Object.assign(task, body);
    return task;
  }
  function deleteTask(id) {
    delete state.tasks[id];
  }
  function createPriority(value) {
    state.priorities[value] = {id: value, name: value};
  }
  function deletePriority(value) {
    delete state.priorities[value];
  }
  function createStatus(value) {
    state.statuses[value] = {id: value, name: value};
  }
  function deleteStatus(value) {
    delete state.statuses[value];
  }
  function listPriorities() {
    const priorityIds = Object.keys(state.priorities);
    return priorityIds.map(id => state.priorities[id]);
  }
  function listStatuses() {
    const statusIds = Object.keys(state.statuses);
    return statusIds.map(id => state.statuses[id]);
  }
  function deleteProject(id) {
    delete state.projects[id];
    delete state.tasks[id];
  }
  function listProjects(filter) {
    const projectIds = Object.keys(state.projects);
    if (filter && filter.projectId) {
      const projectIdsFilter = filter.projectId.toLowerCase();
      const filteredIds = projectIds.filter(id => id.includes(projectIdsFilter));
      return filteredIds.map(id => state.projects[id]);
    }
    return projectIds.map(id => state.projects[id]);
  }
