    if (filter && filter.q) {
      const taskIdsFilter = filter.q.toLowerCase();
      const filteredIds = tasks.filter(task => task.title.toLowerCase().includes(taskIdsFilter));
      return filteredIds.map(task => state.tasks[task.id]);
    }
    return tasks;
  }
  function deleteTaskFilter(filter) {
    const taskIds = Object.keys(state.tasks);
    const tasks = taskIds.map(id => state.tasks[id]);
    if (filter && filter.q) {
      const taskIdsFilter = filter.q.toLowerCase();
      const filteredIds = tasks.filter(task => task.title.toLowerCase().includes(taskIdsFilter));
      return filteredIds.map(task => state.tasks[task.id]);
    }
    return tasks;
  }
  function deleteProjectFilter(filter) {
    const projectIds = Object.keys(state.projects);
    const projectIdsFilter = filter.projectId.toLowerCase();
    const filteredIds = projectIds.filter(id => id.includes(projectIdsFilter));
    return filteredIds.map(id => state.projects[id]);
