const fs = require('node:fs');
function createStore(filePath) {
let state = fs.existsSync(filePath) ? JSON.parse(fs.readFileSync(filePath))
    : { projects: [], tasks: [] };
  return {
    listProjects: () => state.projects,
    createProject: body => {
      const id = String(++state.projects.length);
      return { id, name: body.name, createdAt: new Date().toISOString() };
    },
    updateProject: (id, body) => {
      const project = state.projects.find(p => p.id === id);
      if (!project) throw Error('Invalid project id');
      return { ...project, ...body };
    },
    deleteProject: id => {
      const project = state.projects.find(p => p.id === id);
      if (!project) throw Error('Invalid project id');
      state.projects = state.projects.filter(p => p.id !== id);
      fs.writeFileSync(filePath, JSON.stringify(state));
    },
    listTasks: filter => {
      const filtered = state.tasks.filter(task => {
        const key = Object.keys(task).find(key => filter[key] !== undefined);
        return key !== undefined;
      });
      return filtered.map(task => ({ ...task, projectId: task.projectId
        .split(',')[0], title: task.title.replace(/['"]+/g, '') }));
    },
    createTask: body => {
      const id = String(++state.tasks.length);
      const project = state.projects.find(p => p.id === body.projectId);
      if (!project) throw Error('Invalid project id');
      return { id, projectId: body.projectId, title: body.title, priority:
        body.priority, status: body.status, createdAt: new Date().toISOString() };
    },
    updateTask: (id, body) => {
      const task = state.tasks.find(t => t.id === id);
      if (!task) throw Error('Invalid task id');
      return { ...task, ...body };
    },
    deleteTask: id => {
      const task = state.tasks.find(t => t.id === id);
      if (!task) throw Error('Invalid task id');
      state.tasks = state.tasks.filter(t => t.id !== id);
      fs.writeFileSync(filePath, JSON.stringify(state));
    },
  };
}

