function createStore(filePath) {
let state = fs.existsSync(filePath) ? JSON.parse(fs.readFileSync(filePath))
    : { projects: [], tasks: [] };
  return {
    listProjects: () => state.projects,
    createProject: body => {
      const id = String(++state.projects.length);
      return { id, name: body.name, createdAt: new Date().toISOString() };
    },
    updateProject: (id, body) => {
      const project = state.projects.find(p => p.id === id);
      if (!project) throw Error('Invalid project id');
      return { ...project, ...body };
    },
    deleteProject: id => {
      const project = state.projects.find(p => p.id === id);
      if (!project) throw Error('Invalid project id');
      state.projects = state.projects.filter(p => p.id !== id);
      fs.writeFileSync(filePath, JSON.stringify(state));
    },
    listTasks: filter => {
      const filtered = state.tasks.filter(task => {
      if (!filter || filter === 'all') return true;
      if (filter === 'completed') return task.completed;
      if (filter === 'pending') return task.completed === false;
      if (filter === 'active') return task.completed === true;
      return false;
