    createTask: body => {
      const id = String(++state.tasks.length);
      return { id, title: body.title, description: body.description, completed: false, createdAt: new Date().toISOString() };
    },
    updateTask: (id, body) => {
      const task = state.tasks.find(t => t.id === id);
      if (!task) throw Error('Invalid task id');
      return { ...task, ...body };
    },
    deleteTask: id => {
      const task = state.tasks.find(t => t.id === id);
      if (!task) throw Error('Invalid task id');
      state.tasks = state.tasks.filter(t => t.id !== id);
      fs.writeFileSync(filePath, JSON.stringify(state));
    },
  };
}

