    if (!task) {
      state.projects[projectId].tasks.push(body);
    }
    fs.writeFileSync(filePath, JSON.stringify(state));
    return state.projects[projectId].tasks[body.id];
  }
  function updateTask(id, body) {
    const task = state.projects[body.projectId].tasks.find(task => task.id === id);
    if (task) {
      task.status = body.status;
      task.priority = body.priority;
      task.title = body.title;
      fs.writeFileSync(filePath, JSON.stringify(state));
      return task;
    }
    throw Error('Task not found.');
