    const task = state.projects[body.projectId].tasks.find(task => task.id === id);
    if (task) {
      state.projects[body.projectId].tasks = state.projects[body.projectId].tasks.filter(task => task.id !== id);
      fs.writeFileSync(filePath, JSON.stringify(state));
      return task;
    }
